insert into public.categories (id, slug, name, description, sort_order) values
  ('a1000000-0000-4000-8000-000000000001', 'sauce', '소스', '참기름·들기름부터 비빔장, 조림간장까지. 한 숟갈이면 맛이 잡히는 양념.', 1),
  ('a1000000-0000-4000-8000-000000000002', 'jang', '장류', '고추장, 된장, 간장, 청국장. 찬장의 기본을 항아리에서 천천히.', 2),
  ('a1000000-0000-4000-8000-000000000003', 'jangajji', '장아찌', '간장에 절여 아삭함을 남긴 밥상 단골. 꺼내서 바로 올리세요.', 3),
  ('a1000000-0000-4000-8000-000000000004', 'banchan', '반찬', '매일 꺼내 먹는 작은 찬. 덜 달고 덜 짜게 조렸습니다.', 4),
  ('a1000000-0000-4000-8000-000000000005', 'jeotgal', '젓갈', '명란·창난 같은 밥도둑 젓갈과 국·김치 맛을 잡는 액젓.', 5),
  ('a1000000-0000-4000-8000-000000000006', 'gift', '세트·선물', '고마운 분께, 우리 집 찬장에. 잡사바 대표 상품을 한 상자에.', 6)
