insert into public.events (id, slug, title, description, product_ids, is_active) values
  ('e1000000-0000-4000-8000-000000000001', 'jangdok-week', '장독 위크', '보리고추장, 햇살 된장, 조선간장까지. 항아리에서 익힌 장으로 찬장을 채우는 일주일입니다. 장류 쿠폰 JANG5000을 함께 받아 보세요.', array['5ab00000-0000-4000-8000-000000000008','5ab00000-0000-4000-8000-000000000009','5ab00000-0000-4000-8000-000000000010','5ab00000-0000-4000-8000-000000000011','5ab00000-0000-4000-8000-000000000012','5ab00000-0000-4000-8000-000000000013','5ab00000-0000-4000-8000-000000000014','5ab00000-0000-4000-8000-000000000036']::uuid[], true),
  ('e1000000-0000-4000-8000-000000000002', 'one-plus-one', '1+1 찬장 기획전', '자주 꺼내 쓰는 양념과 젓갈을 두 개 묶음(1+1) 옵션으로 준비했습니다. 상세 페이지에서 ‘1+1’ 옵션을 골라 주세요.', array['5ab00000-0000-4000-8000-000000000004','5ab00000-0000-4000-8000-000000000005','5ab00000-0000-4000-8000-000000000012','5ab00000-0000-4000-8000-000000000019','5ab00000-0000-4000-8000-000000000025','5ab00000-0000-4000-8000-000000000033']::uuid[], true),
  ('e1000000-0000-4000-8000-000000000003', 'aekjeot-week', '국물 맛 잡는 액젓 기획', '멸치·까나리 액젓과 참치액, 그리고 세 가지를 한 번에 담은 액젓 삼종 세트.', array['5ab00000-0000-4000-8000-000000000015','5ab00000-0000-4000-8000-000000000016','5ab00000-0000-4000-8000-000000000017','5ab00000-0000-4000-8000-000000000038']::uuid[], true)
