insert into public.posts (id, board_id, author_name, title, content, is_pinned, product_id) values
  ('d1000000-0000-4000-8000-000000000001', 'b1000000-0000-4000-8000-000000000004', '잡사바', '냉장·냉동 상품은 금·토·일·공휴일에 출고하지 않습니다', '젓갈, 장아찌, 반찬 등 냉장·냉동 상품은 아이스박스와 아이스팩으로 포장해 평일(월~목)에만 출고합니다. 수령 후 바로 냉장해 주세요. 도서산간은 하루가 더 걸릴 수 있습니다.', true, null),
  ('d1000000-0000-4000-8000-000000000002', 'b1000000-0000-4000-8000-000000000004', '잡사바', '비회원 주문은 받지 않습니다', '장바구니는 로그인 전에도 이 브라우저에 남지만, 결제와 적립은 회원만 할 수 있습니다.', false, null),
  ('d1000000-0000-4000-8000-000000000003', 'b1000000-0000-4000-8000-000000000005', '잡사바', '배송은 얼마나 걸리나요?', '평일 오후 2시 전 결제는 당일 출고되고, 대부분 1~2일 안에 도착합니다. 기본 배송비는 3,500원이며 상품 금액 30,000원 이상이면 무료입니다(제주 +3,000원, 도서산간 +5,000원).', true, null),
  ('d1000000-0000-4000-8000-000000000004', 'b1000000-0000-4000-8000-000000000005', '잡사바', '교환과 반품은 어떻게 하나요?', '출고 전에는 주문 상세에서 바로 취소됩니다. 출고 이후에는 수령 후 7일 안에 반품을 요청해 주세요. 냉장·냉동 등 신선식품은 단순 변심에 의한 반품이 제한됩니다.', false, null),
  ('d1000000-0000-4000-8000-000000000005', 'b1000000-0000-4000-8000-000000000005', '잡사바', '포인트는 언제 적립되나요?', '결제 금액 중 상품 대금(배송비 제외, 쿠폰과 포인트 사용 후)의 1%가 결제와 함께 적립됩니다. 1,000P부터 쓸 수 있고, 적립일로부터 1년이 지나면 만료됩니다.', false, null),
  ('d1000000-0000-4000-8000-000000000006', 'b1000000-0000-4000-8000-000000000005', '잡사바', '알레르기 정보는 어디에 있나요?', '상품 상세의 상품정보 탭과 상품정보제공고시 표에 원재료·함량과 알레르기 유발 성분을 적었습니다. 세트 상품은 구성품 라벨을 함께 확인해 주세요.', false, null),
  ('d1000000-0000-4000-8000-000000000007', 'b1000000-0000-4000-8000-000000000001', '잡사바 안내', '양념장 용량은 어떻게 고르나요?', '320g은 2~3주, 1+1(2병)은 한 달 이상 매일 쓰는 집에 맞습니다. 개봉 후 냉장 30일을 기준으로 골라 주세요.', false, null),
  ('d1000000-0000-4000-8000-000000000008', 'b1000000-0000-4000-8000-000000000002', '잡사바 안내', '된장찌개보다 쌈장으로 먼저 드셔 보세요', '햇살 된장은 소금기가 낮습니다. 참기름과 다진 파만 넣어도 쌈장이 됩니다.', false, null),
  ('d1000000-0000-4000-8000-000000000009', 'b1000000-0000-4000-8000-000000000003', '잡사바 안내', '픽업 확인은 글로만 받습니다', '희망 일시와 수령 이름을 글로 남겨 주시면 고객센터가 답글로 확인합니다. 달력 예약이나 자동 확정은 아직 없습니다.', true, null),
  ('d1000000-0000-4000-8000-000000000010', 'b1000000-0000-4000-8000-000000000006', '잡사바 안내', '만능 양념장, 아이들은 얼마나 맵나요?', '청양고추는 들어 있지 않습니다. 매콤 비빔양념보다 훨씬 순하고, 밥에 조금 얹어 맛을 보며 양을 조절하세요.', false, '5ab00000-0000-4000-8000-000000000004')
insert into public.comments (id, post_id, author_name, content, is_admin) values
  ('f1000000-0000-4000-8000-000000000001', 'd1000000-0000-4000-8000-000000000007', '잡사바', '개봉 전이라면 서늘한 실온도 괜찮지만, 여름에는 수령 당일 냉장고에 넣어 주세요.', true)
insert into public.reviews (id, product_id, rating, content, display_name, is_seed, created_at) values
  ('5ab20000-0000-4000-8000-000001000001', '5ab00000-0000-4000-8000-000000000001', 5, '병뚜껑 열자마자 고소한 냄새가 확 올라와요. 나물 무칠 때 양을 반으로 줄여도 충분합니다.', '김*연', true, '2026-09-21T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000001000002', '5ab00000-0000-4000-8000-000000000001', 5, '색이 맑아서 처음엔 연한가 했는데 향이 오래 가요. 간장계란밥 필수템 됐어요.', '박*호', true, '2026-09-02T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000001000003', '5ab00000-0000-4000-8000-000000000001', 4, '부모님께 2병 세트 보냈는데 포장이 꼼꼼했어요. 가격이 조금만 더 착하면 좋겠어요.', '이*진', true, '2026-08-15T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000002000001', '5ab00000-0000-4000-8000-000000000002', 5, '들기름 막국수 해 먹으려고 샀는데 향이 진짜 좋아요. 냉장고에 두고 쓰는 중.', '정*아', true, '2026-09-14T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000002000002', '5ab00000-0000-4000-8000-000000000002', 4, '생들기름이라 그런지 비린 맛 없이 깔끔합니다. 180ml는 금방 써요.', '최*민', true, '2026-08-28T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000003000001', '5ab00000-0000-4000-8000-000000000003', 5, '두부 구워서 뿌려 먹었는데 고소하고 짜지 않아요. 아이들도 잘 먹어요.', '윤*서', true, '2026-10-02T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000003000002', '5ab00000-0000-4000-8000-000000000003', 4, '샤브샤브 소스로 딱이에요. 마늘 향이 은근해서 좋네요.', '한*결', true, '2026-10-04T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000004000001', '5ab00000-0000-4000-8000-000000000004', 5, '제육 양념 매번 만들기 귀찮았는데 이걸로 끝. 남편이 식당 맛이래요.', '오*림', true, '2026-09-25T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000004000002', '5ab00000-0000-4000-8000-000000000004', 5, '1+1로 사서 하나는 친정에 드렸어요. 맵기가 적당해서 아이도 먹어요.', '강*우', true, '2026-09-10T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000004000003', '5ab00000-0000-4000-8000-000000000004', 4, '배 맛이 은은하게 나요. 조금 더 매운 버전도 있으면 좋겠어요.', '서*희', true, '2026-08-30T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000005000001', '5ab00000-0000-4000-8000-000000000005', 5, '여름 내내 비빔국수 해 먹었어요. 새콤달콤 비율이 딱 좋아요.', '임*수', true, '2026-08-20T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000005000002', '5ab00000-0000-4000-8000-000000000005', 4, '생각보다 맵지 않고 산뜻해요. 회덮밥에도 잘 어울립니다.', '조*은', true, '2026-09-05T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000006000001', '5ab00000-0000-4000-8000-000000000006', 5, '감자조림이 한 번에 성공했어요. 단맛이 과하지 않아 좋아요.', '배*나', true, '2026-10-05T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000006000002', '5ab00000-0000-4000-8000-000000000006', 4, '불고기 재울 때 썼는데 간이 딱 맞네요. 큰 병으로 재구매 예정.', '신*혁', true, '2026-10-06T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000007000001', '5ab00000-0000-4000-8000-000000000007', 5, '시판 초장보다 덜 달고 깔끔해요. 회 먹는 날 필수.', '문*지', true, '2026-09-18T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000007000002', '5ab00000-0000-4000-8000-000000000007', 4, '숙회 찍어 먹기 좋아요. 매실 향이 살짝 나요.', '장*호', true, '2026-08-11T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000008000001', '5ab00000-0000-4000-8000-000000000008', 5, '보리 들어간 고추장은 처음인데 구수해서 깜짝 놀랐어요. 찌개가 텁텁하지 않아요.', '유*경', true, '2026-10-01T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000008000002', '5ab00000-0000-4000-8000-000000000008', 5, '항아리째 받으니 선물 같아요. 맛도 시골 할머니 고추장 느낌.', '노*수', true, '2026-09-27T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000008000003', '5ab00000-0000-4000-8000-000000000008', 4, '칼칼하고 덜 달아요. 단맛 좋아하시면 조청 조금 더 넣으세요.', '황*린', true, '2026-09-24T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000009000001', '5ab00000-0000-4000-8000-000000000009', 5, '색이 정말 예뻐요. 떡볶이 하면 빛깔부터 달라요.', '송*아', true, '2026-09-12T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000009000002', '5ab00000-0000-4000-8000-000000000009', 4, '덜 달아서 좋아요. 매운맛은 중간 정도.', '권*민', true, '2026-08-03T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000010000001', '5ab00000-0000-4000-8000-000000000010', 5, '짜지 않아서 국을 넉넉히 끓여도 좋아요. 콩 향이 진합니다.', '엄*희', true, '2026-09-08T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000010000002', '5ab00000-0000-4000-8000-000000000010', 5, '쌈장으로 먹으려고 샀다가 찌개까지 이걸로 바꿨어요.', '차*준', true, '2026-08-22T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000011000001', '5ab00000-0000-4000-8000-000000000011', 5, '냄새가 생각보다 순해서 아파트에서도 부담 없어요. 소분돼 있어 편합니다.', '구*선', true, '2026-10-03T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000011000002', '5ab00000-0000-4000-8000-000000000011', 4, '콩이 살아 있어서 식감이 좋아요. 6팩으로 다시 살게요.', '안*영', true, '2026-10-05T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000012000001', '5ab00000-0000-4000-8000-000000000012', 5, '캠핑 갈 때마다 챙겨요. 땅콩이 씹혀서 고소해요.', '홍*진', true, '2026-08-17T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000012000002', '5ab00000-0000-4000-8000-000000000012', 4, '시판 쌈장보다 덜 달고 된장 맛이 진해요.', '백*호', true, '2026-07-29T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000013000001', '5ab00000-0000-4000-8000-000000000013', 5, '미역국 끓일 때 이 간장 넣으면 국물이 맑고 맛있어요.', '전*숙', true, '2026-09-03T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000013000002', '5ab00000-0000-4000-8000-000000000013', 4, '짠맛이 강하니 조금씩 넣으세요. 나물 무침에 최고.', '류*아', true, '2026-08-09T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000014000001', '5ab00000-0000-4000-8000-000000000014', 5, '간장계란밥 해 먹으니 확실히 향이 달라요.', '고*현', true, '2026-09-19T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000014000002', '5ab00000-0000-4000-8000-000000000014', 4, '무난하게 다 잘 어울려요. 큰 병이 가성비 좋아요.', '남*원', true, '2026-08-25T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000015000001', '5ab00000-0000-4000-8000-000000000015', 5, '김장할 때 이걸로 했는데 비린 맛이 없어요. 시원한 맛이 나요.', '민*경', true, '2026-09-29T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000015000002', '5ab00000-0000-4000-8000-000000000015', 5, '국 끓일 때 소금 대신 쓰는데 맛이 확 살아요.', '이*호', true, '2026-09-11T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000016000001', '5ab00000-0000-4000-8000-000000000016', 5, '겉절이 맛이 깔끔해졌어요. 멸치액젓이랑 섞어 쓰기도 해요.', '윤*정', true, '2026-09-16T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000016000002', '5ab00000-0000-4000-8000-000000000016', 4, '향이 강하지 않아서 처음 액젓 쓰는 사람한테도 좋아요.', '표*수', true, '2026-08-19T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000017000001', '5ab00000-0000-4000-8000-000000000017', 5, '어묵탕 끓일 때 한 숟갈 넣으니 가게 맛이 나요.', '조*린', true, '2026-10-02T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000017000002', '5ab00000-0000-4000-8000-000000000017', 5, '계란말이에 넣는 게 최고예요. 아이 반찬 필수템.', '김*빈', true, '2026-09-26T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000017000003', '5ab00000-0000-4000-8000-000000000017', 4, '국물이 쉽게 맛있어져요. 조금만 넣어도 됩니다.', '설*아', true, '2026-09-23T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000018000001', '5ab00000-0000-4000-8000-000000000018', 5, '짜지 않아서 그냥 먹어도 맛있어요. 알이 탱글탱글.', '하*연', true, '2026-09-30T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000018000002', '5ab00000-0000-4000-8000-000000000018', 5, '명란 파스타 해 먹었는데 색소 없는 게 마음에 들어요.', '진*우', true, '2026-09-13T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000019000001', '5ab00000-0000-4000-8000-000000000019', 5, '식감이 정말 좋아요. 밥 두 공기 순삭.', '석*희', true, '2026-09-07T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000019000002', '5ab00000-0000-4000-8000-000000000019', 4, '생각보다 덜 짜고 달콤해요.', '마*준', true, '2026-08-14T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000020000001', '5ab00000-0000-4000-8000-000000000020', 5, '몸통만이라 그런지 식감이 고급져요.', '권*나', true, '2026-09-20T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000020000002', '5ab00000-0000-4000-8000-000000000020', 4, '아이도 잘 먹을 정도로 순해요. 매운 거 좋아하면 고춧가루 추가!', '양*석', true, '2026-08-31T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000021000001', '5ab00000-0000-4000-8000-000000000021', 5, '굴이 작고 탱탱해요. 보쌈이랑 같이 먹으니 최고.', '오*숙', true, '2026-10-05T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000021000002', '5ab00000-0000-4000-8000-000000000021', 4, '칼칼하고 맛있는데 빨리 먹어야 해서 소량이 딱 좋아요.', '김*태', true, '2026-10-06T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000022000001', '5ab00000-0000-4000-8000-000000000022', 5, '새우가 통통하고 국물이 맑아요. 수육 먹을 때 꼭 꺼내요.', '정*호', true, '2026-09-04T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000022000002', '5ab00000-0000-4000-8000-000000000022', 4, '김장용으로 500g 샀어요. 짜지만 원래 그런 맛!', '허*진', true, '2026-08-27T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000023000001', '5ab00000-0000-4000-8000-000000000023', 5, '고향 맛이에요. 호박잎 쌈에 올려 먹으니 옛날 생각나요.', '나*수', true, '2026-08-30T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000023000002', '5ab00000-0000-4000-8000-000000000023', 4, '처음엔 낯설었는데 삼겹살이랑 먹으니 중독돼요.', '변*아', true, '2026-08-12T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000024000001', '5ab00000-0000-4000-8000-000000000024', 5, '아삭하고 하나도 안 매워요. 고기 먹을 때 필수.', '곽*연', true, '2026-09-15T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000024000002', '5ab00000-0000-4000-8000-000000000024', 4, '단짠 비율 좋아요. 국물도 요리에 씁니다.', '엄*훈', true, '2026-08-21T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000025000001', '5ab00000-0000-4000-8000-000000000025', 5, '엄마가 해주던 맛이에요. 짜지 않아서 많이 먹게 돼요.', '이*아', true, '2026-09-22T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000025000002', '5ab00000-0000-4000-8000-000000000025', 5, '깻잎 향이 진하고 양념이 넉넉해요.', '도*현', true, '2026-09-01T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000026000001', '5ab00000-0000-4000-8000-000000000026', 5, '라면 먹을 때 꼭 꺼내요. 맵지만 계속 손이 가요.', '추*민', true, '2026-08-26T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000026000002', '5ab00000-0000-4000-8000-000000000026', 4, '생각보다 달큰해요. 아주 매운 걸 원하시면 참고하세요.', '봉*희', true, '2026-08-02T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000027000001', '5ab00000-0000-4000-8000-000000000027', 5, '고기 먹을 때 이것만 있으면 돼요. 새콤달콤!', '염*정', true, '2026-10-03T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000027000002', '5ab00000-0000-4000-8000-000000000027', 4, '아삭하고 맛있어요. 국물에 청양 들어가서 살짝 칼칼해요.', '피*수', true, '2026-10-04T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000028000001', '5ab00000-0000-4000-8000-000000000028', 5, '꼬들꼬들 식감 최고예요. 죽이랑 먹기 좋아요.', '경*아', true, '2026-08-18T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000028000002', '5ab00000-0000-4000-8000-000000000028', 4, '무쳐 먹으니 할머니 반찬 같아요.', '탁*진', true, '2026-07-30T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000029000001', '5ab00000-0000-4000-8000-000000000029', 5, '아삭함이 오래 가요. 밥도둑입니다.', '문*호', true, '2026-08-08T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000029000002', '5ab00000-0000-4000-8000-000000000029', 4, '간이 딱 좋아요. 양이 조금 더 많으면 좋겠어요.', '심*연', true, '2026-07-25T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000030000001', '5ab00000-0000-4000-8000-000000000030', 5, '아이 도시락에 매일 넣어요. 딱딱하지 않고 바삭해요.', '이*솔', true, '2026-09-28T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000030000002', '5ab00000-0000-4000-8000-000000000030', 5, '달지 않아서 어른 입맛에도 좋아요.', '최*영', true, '2026-09-09T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000031000001', '5ab00000-0000-4000-8000-000000000031', 5, '고기가 정말 부드러워요. 메추리알도 넉넉!', '강*희', true, '2026-09-17T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000031000002', '5ab00000-0000-4000-8000-000000000031', 4, '짜지 않아서 아이들이 잘 먹어요.', '유*준', true, '2026-08-29T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000032000001', '5ab00000-0000-4000-8000-000000000032', 5, '김밥 쌀 때 이거 하나면 편해요. 맛도 좋아요.', '임*아', true, '2026-08-24T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000032000002', '5ab00000-0000-4000-8000-000000000032', 4, '달큰하고 쫄깃해요. 양이 조금 적은 느낌.', '황*수', true, '2026-08-06T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000033000001', '5ab00000-0000-4000-8000-000000000033', 5, '딱딱하지 않아서 어르신들도 잘 드세요.', '방*연', true, '2026-09-06T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000033000002', '5ab00000-0000-4000-8000-000000000033', 4, '적당히 달고 윤기가 좌르르.', '채*민', true, '2026-08-16T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000034000001', '5ab00000-0000-4000-8000-000000000034', 5, '오독오독 식감이 너무 좋아요. 보쌈이랑 찰떡.', '노*아', true, '2026-10-02T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000034000002', '5ab00000-0000-4000-8000-000000000034', 4, '맵기 적당하고 고춧잎 향이 좋아요.', '서*진', true, '2026-10-04T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000035000001', '5ab00000-0000-4000-8000-000000000035', 5, '진짜 안 딱딱해요. 남편 도시락 반찬 1순위.', '주*희', true, '2026-09-19T12:00:00+09:00'),
  ('5ab20000-0000-4000-8000-000035000002', '5ab00000-0000-4000-8000-000000000035', 4, '달콤해서 아이가 잘 먹어요.', '오*석', true, '2026-08-23T12:00:00+09:00'),
